# Ukkonen's Suffix Tree Algorithm

### Implementation

```python
class SuffixTreeNode:
    def __init__(self, label):
        self.label = label
        self.children = {}
        self.next = None

class SuffixTree:
    def __init__(self, string):
        self.root = SuffixTreeNode("")
        self.string = string
        self.current_node = self.root
        self.active_point = 0

    def build(self):
        for i in range(len(self.string)):
            self.add_suffix(self.string[i:])

    def add_suffix(self, suffix):
        current_node = self.current_node
        for char in suffix:
            if char not in current_node.children:
                new_node = SuffixTreeNode(char)
                current_node.children[char] = new_node
            current_node = current_node.children[char]
            current_node.next = self.active_point
            self.active_point += 1
        current_node.label = suffix

    def canonize(self):
        self.root = self._canonize(self.root)

    def _canonize(self, node):
        if not node.children:
            return node
        children = list(node.children.values())
        max_child = max(children, key=lambda x: x.label)
        node.children = {}
        for child in children:
            if child != max_child:
                node.children[child.label] = self._canonize(child)
        return max_child

    def print_tree(self):
        self._print_tree(self.root)

    def _print_tree(self, node, level=0):
        print('  ' * level + node.label)
        for child in node.children.values():
            self._print_tree(child, level + 1)
```

### Usage

```python
string = "banana"
tree = SuffixTree(string)
tree.build()
tree.canonize()
tree.print_tree()
```

This implementation provides a basic suffix tree construction algorithm, automatic canonization, and a method to print the tree. The `build` method constructs the tree by adding all suffixes of the input string, the `canonize` method applies the canonization process to the tree, and the `print_tree` method prints the tree in a readable format.

class Stack:
    def __init__(self, max_size):
        self.max_size = max_size
        self.stack = []

    def push(self, item):
        if len(self.stack) < self.max_size:
            self.stack.append(item)
        else:
            raise Exception('Stack is full')

    def pop(self):
        if not self.is_empty():
            return self.stack.pop()
        else:
            raise Exception('Stack is empty')

    def is_empty(self):
        return len(self.stack) == 0

def tail_call_optimization(n):
    stack = Stack(n)
    def recursive_function(x):
        if x == 0:
            return
        stack.push(x)
        recursive_function(x-1)
        stack.pop()
    recursive_function(n)

