def update_object(id):
    object_data = request.get_json()
    if id in objects:
        objects[id] = object_data
        return jsonify(object_data), 200
    else:
        return jsonify({'error': 'Object not found'}), 404

@app.route('/objects', methods=['POST'])
def create_object():
    object_data = request.get_json()
    id = object_data['id']
    if id in objects:
        return jsonify({'error': 'Object already exists'}), 409
    else:
        objects[id] = object_data
        return jsonify(object_data), 201

