# Differences between type() and isinstance():
# type() checks if the object is of a specific type, 
# while isinstance() checks if the object is of a specific type or its subclasses.

def compare_types():
    class CustomDict(dict):
        pass

    a = CustomDict()
    b = "Hello"
    c = 123

    # Using type()
    if type(a) is dict:
        print("a is a dict")
    else:
        print("a is not a dict")

    if type(b) in (str, bytes):
        print("b is a string")
    else:
        print("b is not a string")

    if type(c) in (int, float):
        print("c is a number")
    else:
        print("c is not a number")

    # Using isinstance()
    if isinstance(a, dict):
        print("a is a dict")
    else:
        print("a is not a dict")

    if isinstance(b, (str, bytes)):
        print("b is a string")
    else:
        print("b is not a string")

    if isinstance(c, (int, float)):
        print("c is a number")
    else:
        print("c is not a number")

compare_types()
